cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);

// Basic counts
const total = data.length;
const confirmed = data.filter(r => r.Status === 'confirmed').length;
const cancelled = data.filter(r => r.Status === 'cancelled').length;

// Revenue
const totalRevenue = data.reduce((s,r) => s + (r['Total Paid'] || 0), 0);
const confirmedRevenue = data.filter(r => r.Status === 'confirmed').reduce((s,r) => s + (r['Total Paid'] || 0), 0);
const cancelledRevenue = data.filter(r => r.Status === 'cancelled').reduce((s,r) => s + (r['Total Paid'] || 0), 0);

// By customer
const byCust = {};
data.forEach(r => {
  const c = r.Customer;
  if (!byCust[c]) byCust[c] = {orders: 0, revenue: 0, confirmed: 0, cancelled: 0};
  byCust[c].orders++;
  byCust[c].revenue += r['Total Paid'] || 0;
  byCust[c][r.Status]++;
});

// Top products
const products = {};
data.forEach(r => {
  (r.Items || '').split(',').map(s => s.trim()).filter(Boolean).forEach(p => {
    if (!products[p]) products[p] = 0;
    products[p]++;
  });
});

console.log('--- ORDER SUMMARY ---');
console.log('Total orders:', total);
console.log('  Confirmed:', confirmed);
console.log('  Cancelled:', cancelled);
console.log();
console.log('Total revenue (all orders):  \$' + totalRevenue);
console.log('Confirmed order revenue:     \$' + confirmedRevenue);
console.log('Cancelled order revenue:     \$' + cancelledRevenue);
console.log('Average order value:         \$' + (totalRevenue / total).toFixed(2));
console.log();
console.log('--- ORDERS BY CUSTOMER ---');
Object.entries(byCust)
  .sort((a,b) => b[1].revenue - a[1].revenue)
  .forEach(([c, v]) => {
    console.log('  ' + c + ': ' + v.orders + ' orders, \$' + v.revenue + ' total (' + v.confirmed + ' confirmed, ' + v.cancelled + ' cancelled)');
  });
console.log();
console.log('--- PRODUCT FREQUENCY (appearances in orders) ---');
Object.entries(products)
  .sort((a,b) => b[1] - a[1])
  .forEach(([p, c]) => console.log('  ' + p + ': ' + c));

console.log();
console.log('Date range:', [...new Set(data.map(r => r.Date))].sort().join(', '));
"
